import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CCCdsIgc.js";const p=JSON.parse('{"title":"文件、预览与还原","description":"","frontmatter":{},"headers":[],"relativePath":"guide/files.md","filePath":"guide/files.md"}'),r={name:"guide/files.md"};function o(s,a,n,d,c,u){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="文件、预览与还原" tabindex="-1">文件、预览与还原 <a class="header-anchor" href="#文件、预览与还原" aria-label="Permalink to &quot;文件、预览与还原&quot;">​</a></h1><h2 id="产出文件" tabindex="-1">产出文件 <a class="header-anchor" href="#产出文件" aria-label="Permalink to &quot;产出文件&quot;">​</a></h2><p>任务生成文件后，对话里出现文件卡片：</p><ul><li><strong>预览</strong>：在右侧分屏打开，支持 Word、Excel、PPT、PDF、图片、网页、CSV、代码、压缩包；</li><li>小箭头里可以「用默认应用打开」「在文件资源管理器中显示」。</li></ul><p>用过、生成过的文件会自动收进侧栏的<strong>资料库</strong>，按图片、文档、收藏分类，下次一句话就能找到。</p><h2 id="改动与一键还原" tabindex="-1">改动与一键还原 <a class="header-anchor" href="#改动与一键还原" aria-label="Permalink to &quot;改动与一键还原&quot;">​</a></h2><p>办事的回答下面会出现「<strong>改动了 N 个文件</strong>」，点开能看到这一轮新建、修改、删除了哪些文件：</p><ul><li>文本和 Word 逐行对比，Excel / CSV 标出改过的格子（鼠标停上去看原值）；</li><li>在某一行、某个格子上写修改意见，点「让 AI 按意见修改」一次交给 AI；</li><li>「全部还原」「还原选中」把文件退回这一轮开始之前。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>通过命令改过的已有文件事先没有备份，只能列出来、手动处理。</p></div><h2 id="文档画布" tabindex="-1">文档画布 <a class="header-anchor" href="#文档画布" aria-label="Permalink to &quot;文档画布&quot;">​</a></h2><p>让 AI 写报告、方案、通知这类成篇的文字时，右侧「文档」标签里直接打开：</p><ul><li>像在 Word 里一样编辑，停下来自动保存；</li><li>选中一段点「让 AI 改」，说清怎么改就行，AI 只改那一段；</li><li>一键导出 Word，也能打印或另存为 PDF。</li></ul><h2 id="右侧面板" tabindex="-1">右侧面板 <a class="header-anchor" href="#右侧面板" aria-label="Permalink to &quot;右侧面板&quot;">​</a></h2><ul><li><strong>文件</strong>：浏览、搜索工作区里的文件（只读）；</li><li><strong>上下分屏 / 铺满</strong>：一边看文档一边看终端，或者铺满看大表格。</li></ul>',14)])])}const _=l(r,[["render",o]]);export{p as __pageData,_ as default};
